import os
import time
import re
import glob
from taf.converters.base import OutputFileMapper
from taf.converters.pcaptopdml import pcaptopdml
from taf.ul.parser.pcap.exceptions import FileNotExist


class Converter(object):
    _DEFAULT_COMMAND_TEMPLATE = "{tshark_path} -r {input_file}  -T pdml > {output_file}"

    def __init__(self):
        self._converter = pcaptopdml()

    def convert_pcap_to_pdml(self, pcap_file, tshark_path=None, luashark_path=None, command_template=None):
        if not os.path.exists(pcap_file):
            raise FileNotExist("{} does not exist!".format(pcap_file))
        if luashark_path and not os.path.exists(luashark_path):
            raise FileNotExist("{} does not exist!".format(luashark_path))
        pcap_file = Converter.escape(pcap_file)
        name = "pcap_parser_converter_{}".format(time.time())
        command_template = command_template if luashark_path or command_template else self._DEFAULT_COMMAND_TEMPLATE
        self._converter.create_pcap_to_pdml_converter(name, pcap_file, tshark_path, luashark_path, command_template)
        output_file = OutputFileMapper(output_extension=".pdml").map(pcap_file)
        self._converter.convert(name)
        return glob.glob(output_file)[0]

    @staticmethod
    def escape(pathname):
        """
        Escape all special characters.
        """
        # Escaping is done by wrapping any of "*?[" between square brackets.
        # Metacharacters do not work in the drive part and shouldn't be escaped.
        magic_check = re.compile('([*?[])')
        magic_check_bytes = re.compile(b'([*?[])')
        drive, pathname = os.path.splitdrive(pathname)
        if isinstance(pathname, bytes):
            pathname = magic_check_bytes.sub(br'[\1]', pathname)
        else:
            pathname = magic_check.sub(r'[\1]', pathname)
        return drive + pathname
